// Aspecto de cada tira del catálogo, medido en las fotos del producto: PVC brillante;
// la dorada, la rosada y la plateada son translúcidas (se ve la suela y los bordes se oscurecen)
type StrapLook = { color: string; op: number; rough: number; metal: number; glitter: number; flake: number; edge: number; coat: number; coatRough: number };
const STRAP_LOOK: Record<string, StrapLook> = {
	bronce: { color: '#B08E5C', op: 0.62, rough: 0.08, metal: 0.05, glitter: 0.3, flake: 0.3, edge: 0.9, coat: 1, coatRough: 0.03 },
	rosa: { color: '#C98E9E', op: 0.62, rough: 0.08, metal: 0.05, glitter: 0.28, flake: 0.3, edge: 0.9, coat: 1, coatRough: 0.03 },
	'negra-escarcha': { color: '#141418', op: 1, rough: 0.07, metal: 0.05, glitter: 0.5, flake: 0.45, edge: 0, coat: 1, coatRough: 0.03 },
	negra: { color: '#0E0E10', op: 1, rough: 0.07, metal: 0, glitter: 0, flake: 0, edge: 0, coat: 1, coatRough: 0.03 },
	plata: { color: '#A3A6AB', op: 0.45, rough: 0.08, metal: 0, glitter: 0, flake: 0.05, edge: 0.95, coat: 1, coatRough: 0.03 },
	blanco: { color: '#DCDCD8', op: 1, rough: 0.1, metal: 0, glitter: 0, flake: 0, edge: 0, coat: 1, coatRough: 0.03 },
};

const smoothK = (a: number, b: number, x: number) => {
	const k = Math.min(1, Math.max(0, (x - a) / (b - a)));
	return k * k * (3 - 2 * k);
};

// Huecos donde la tira entra en la suela, ajustados a las fotos de producto: un poco más adentro
// y más arriba que en el molde, porque la tira llega curvada hacia el centro
const STRAP_HOLES = HOLES.map((h) => {
	const dir = Math.sign(h.med[0] - h.lat[0]);
	return { toe: h.toe, med: [h.med[0] - dir * 10, h.med[1] - 6], lat: [h.lat[0] + dir * 10, h.lat[1] - 6] };
});

// Recorrido de la tira medido en las fotos de producto (vista desde arriba, tira de pie):
// sale del nudo, que queda detrás del hueco del dedo, en diagonal hasta el borde de la suela,
// baja pegada al borde y al final se recoge hacia adentro para entrar en el hueco.
// Las fracciones son la distancia al borde (interno o externo) sobre el ancho de la suela.
function strapLegsKite(poly: number[][], medialRight: boolean, holes: { toe: number[]; med: number[]; lat: number[] }) {
	let y0 = Infinity;
	let y1 = -Infinity;
	for (const q of poly) {
		if (q[1] < y0) y0 = q[1];
		if (q[1] > y1) y1 = q[1];
	}
	const H = y1 - y0;
	const at = (f: number, fromMedial: number) => {
		const y = y0 + f * H;
		const [l, r] = edgesAt(poly, y);
		const w = r - l;
		return [medialRight ? r - fromMedial * w : l + fromMedial * w, y];
	};
	const post = holes.toe.slice();
	const apexF = (post[1] - y0) / H + 0.05;
	const apex = at(apexF, 0.43);
	const FS = [0.3, 0.35, 0.4, 0.45, 0.5, 0.55, 0.6, 0.65, 0.7];
	const MED = [0.27, 0.17, 0.08, 0.035, 0.025, 0.03, 0.045, 0.085, 0.15];
	const LAT = [0.35, 0.23, 0.12, 0.045, 0.03, 0.03, 0.05, 0.09, 0.155];
	const leg = (IN: number[], end: number[]) => {
		const out = [apex.slice()];
		const endF = (end[1] - y0) / H;
		FS.forEach((f, k) => {
			if (f > apexF + 0.02 && f < endF - 0.012) out.push(at(f, IN[k]));
		});
		out.push(end.slice());
		return out;
	};
	return { post, apex, legs: [leg(MED, holes.med), leg(LAT.map((v) => 1 - v), holes.lat)] };
}

// Tira como banda plana de PVC brillante (como la real): sección de rectángulo redondeado de 1,2 cm,
// cara arriba junto al nudo, inclinada hacia afuera a los lados del pie y otra vez de cara al entrar
// en el hueco. 1 px de la foto ≈ 0,29 mm.
function strapGeo(T: Any, p: number[][]) {
	const out = Math.sign(p[p.length - 1][0] - p[0][0]) || 1;
	const len = [0];
	for (let i = 1; i < p.length; i++) len.push(len[i - 1] + Math.hypot(p[i][0] - p[i - 1][0], p[i][1] - p[i - 1][1]));
	const tot = len[len.length - 1];
	const P = p.map((q, i) => {
		const t = len[i] / tot;
		return new T.Vector3(q[0], SOLE_TOP + (1 - Math.pow(t, 5)) * (62 + 44 * Math.sin(Math.PI * t * 0.85)), q[1]);
	});
	const e = p[p.length - 1];
	P.push(new T.Vector3(e[0], SOLE_TOP - 12, e[1] + 4));
	const curve = new T.CatmullRomCurve3(P, false, 'centripetal');
	const L = curve.getLength();
	const N = 150;
	const M = 22;
	const ex = 2 / 3.4;
	const up = new T.Vector3(0, 1, 0);
	const pos: number[] = [];
	const uv: number[] = [];
	const idx: number[] = [];
	let firstC: Any = null;
	for (let i = 0; i <= N; i++) {
		const u = i / N;
		const C = curve.getPointAt(u);
		const Tn = curve.getTangentAt(u).normalize();
		const W = new T.Vector3().crossVectors(Tn, up);
		if (W.lengthSq() < 1e-6) W.set(out, 0, 0);
		W.normalize();
		if (W.x * out < 0) W.negate();
		const Nn = new T.Vector3().crossVectors(W, Tn).normalize();
		if (Nn.y < 0) Nn.negate();
		const a = 0.12 + 0.5 * smoothK(0.12, 0.42, u) - 0.4 * smoothK(0.7, 0.98, u);
		const W2 = W.clone().multiplyScalar(Math.cos(a)).addScaledVector(Nn, -Math.sin(a)).normalize();
		const D = new T.Vector3().crossVectors(W2, Tn).normalize();
		if (D.dot(Nn) < 0) D.negate();
		const hw = 19 + 2 * smoothK(0, 0.18, u) - 2 * smoothK(0.9, 1, u);
		const ht = 5.2 - 0.4 * smoothK(0.08, 0.45, u);
		if (i === 0) firstC = C.clone();
		for (let j = 0; j < M; j++) {
			const th = -Math.PI / 2 + (j / M) * Math.PI * 2;
			const c = Math.cos(th);
			const s = Math.sin(th);
			const q = C.clone()
				.addScaledVector(W2, Math.sign(c) * Math.pow(Math.abs(c), ex) * hw)
				.addScaledVector(D, Math.sign(s) * Math.pow(Math.abs(s), ex) * ht);
			pos.push(q.x, q.y, q.z);
			uv.push((u * L) / 110, ((j / M) * (4 * hw + 4 * ht)) / 110);
		}
	}
	for (let i = 0; i < N; i++) {
		for (let j = 0; j < M; j++) {
			const a = i * M + j;
			const b = i * M + ((j + 1) % M);
			const c = (i + 1) * M + j;
			const d = (i + 1) * M + ((j + 1) % M);
			idx.push(a, c, b, b, c, d);
		}
	}
	const geo = new T.BufferGeometry();
	geo.setAttribute('position', new T.Float32BufferAttribute(pos, 3));
	geo.setAttribute('uv', new T.Float32BufferAttribute(uv, 2));
	geo.setIndex(idx);
	geo.computeVertexNormals();
	// Caras hacia afuera: la normal del borde exterior debe apuntar lejos del centro de la tira
	const n = geo.attributes.normal;
	const k = M / 4;
	const nv = new T.Vector3(n.getX(k), n.getY(k), n.getZ(k));
	const pv = new T.Vector3(pos[k * 3], pos[k * 3 + 1], pos[k * 3 + 2]).sub(firstC);
	if (nv.dot(pv) < 0) {
		for (let t = 0; t < idx.length; t += 3) {
			const s = idx[t + 1];
			idx[t + 1] = idx[t + 2];
			idx[t + 2] = s;
		}
		geo.setIndex(idx);
		geo.computeVertexNormals();
	}
	return geo;
}

// Poste del dedo como en la foto: sale del nudo hacia adelante y baja al hueco de la suela
function postStub(T: Any, post: number[], apex: number[]) {
	const top = new T.Vector3(apex[0], SOLE_TOP + 62, apex[1]);
	const mid = new T.Vector3(post[0] + (apex[0] - post[0]) * 0.35, SOLE_TOP + 34, post[1] + (apex[1] - post[1]) * 0.3);
	const bot = new T.Vector3(post[0], SOLE_TOP - 10, post[1]);
	const tube = new T.TubeGeometry(new T.CatmullRomCurve3([top, mid, bot], false, 'centripetal'), 24, 8, 20, false);
	const head = new T.SphereGeometry(13, 40, 24);
	head.scale(1.3, 0.42, 1);
	head.translate(top.x, top.y - 2, top.z + 2);
	return [tube, head];
}

// Escarcha: escamas que reflejan la luz en distintas direcciones (brillan al girar) y puntos finos
function strapTextures(T: Any) {
	const S = 256;
	const fc = document.createElement('canvas');
	fc.width = fc.height = S;
	const fx = fc.getContext('2d') as CanvasRenderingContext2D;
	fx.fillStyle = 'rgb(128,128,255)';
	fx.fillRect(0, 0, S, S);
	for (let i = 0; i < 2600; i++) {
		const nx = (Math.random() - 0.5) * 1.3;
		const ny = (Math.random() - 0.5) * 1.3;
		const l = Math.hypot(nx, ny, 1);
		fx.fillStyle = 'rgb(' + Math.round((nx / l / 2 + 0.5) * 255) + ',' + Math.round((ny / l / 2 + 0.5) * 255) + ',' + Math.round((1 / l / 2 + 0.5) * 255) + ')';
		const z = Math.random() < 0.3 ? 2 : 1;
		fx.fillRect(Math.floor(Math.random() * S), Math.floor(Math.random() * S), z, z);
	}
	const flake = new T.CanvasTexture(fc);
	flake.wrapS = flake.wrapT = T.RepeatWrapping;
	flake.colorSpace = T.NoColorSpace;
	const gc = document.createElement('canvas');
	gc.width = gc.height = S;
	const gx = gc.getContext('2d') as CanvasRenderingContext2D;
	gx.fillStyle = '#000';
	gx.fillRect(0, 0, S, S);
	for (let i = 0; i < 520; i++) {
		const v = 150 + Math.floor(Math.random() * 105);
		gx.fillStyle = 'rgb(' + v + ',' + v + ',' + v + ')';
		gx.fillRect(Math.floor(Math.random() * S), Math.floor(Math.random() * S), 1, 1);
	}
	const glit = new T.CanvasTexture(gc);
	glit.wrapS = glit.wrapT = T.RepeatWrapping;
	return { flake, glit };
}

// PVC brillante; en las tiras translúcidas los bordes se ven más opacos y oscuros, como en la foto
function strapMaterial(T: Any, tx: { flake: Any; glit: Any }) {
	const m = new T.MeshPhysicalMaterial({
		color: 0x7a5c3a,
		roughness: 0.1,
		metalness: 0.05,
		clearcoat: 1,
		clearcoatRoughness: 0.06,
		normalMap: tx.flake,
		normalScale: new T.Vector2(0.3, 0.3),
		emissive: 0xffffff,
		emissiveMap: tx.glit,
		emissiveIntensity: 0,
	});
	m.userData.edge = { value: 0 };
	m.onBeforeCompile = (sh: Any) => {
		sh.uniforms.uEdge = m.userData.edge;
		sh.fragmentShader =
			'uniform float uEdge;\n' +
			sh.fragmentShader.replace(
				'#include <opaque_fragment>',
				'float sFr = 1.0 - abs(dot(normalize(normal), normalize(vViewPosition)));\n\tfloat sEd = clamp(uEdge * sFr * sFr * 1.8, 0.0, 1.0);\n\tdiffuseColor.a = mix(diffuseColor.a, 1.0, sEd);\n\toutgoingLight *= mix(1.0, 0.6, sEd);\n\t#include <opaque_fragment>',
			);
	};
	return m;
}

function applyStrapLook(m: Any, look: StrapLook) {
	m.color.set(look.color);
	m.metalness = look.metal;
	m.roughness = look.rough;
	m.transparent = look.op < 1;
	m.opacity = look.op;
	m.emissiveIntensity = look.glitter;
	m.normalScale.set(look.flake, look.flake);
	m.userData.edge.value = look.edge;
	m.clearcoat = look.coat;
	m.clearcoatRoughness = look.coatRough;
	m.needsUpdate = true;
}

// Luz de estudio solo para la tira: cajas de luz delgadas que dan los reflejos largos de las fotos
function strapEnv(T: Any, renderer: Any) {
	const pm = new T.PMREMGenerator(renderer);
	const sc = new T.Scene();
	sc.add(new T.Mesh(new T.BoxGeometry(14, 14, 14), new T.MeshBasicMaterial({ color: new T.Color().setScalar(0.32), side: T.BackSide })));
	const box = (w: number, h: number, x: number, y: number, z: number, k: number) => {
		const m = new T.Mesh(new T.PlaneGeometry(w, h), new T.MeshBasicMaterial({ color: new T.Color().setScalar(k), side: T.DoubleSide }));
		m.position.set(x, y, z);
		m.lookAt(0, 0, 0);
		sc.add(m);
	};
	box(6, 2.2, 0, 6, 0.5, 5);
	box(0.7, 7, -4, 4, 2.5, 9);
	box(0.6, 7, 4.5, 3.5, 1, 6.3);
	box(6, 0.6, 0, 3, 5, 5.4);
	box(5, 0.6, 0, 3, -5, 4.5);
	const t = pm.fromScene(sc, 0.02).texture;
	sc.traverse((o: Any) => {
		if (o.geometry) o.geometry.dispose();
		if (o.material) o.material.dispose();
	});
	pm.dispose();
	return t;
}

// Grano fino de la goma EVA de la suela (relieve muy leve)
function grainTexture(T: Any) {
	const S = 256;
	const nc = document.createElement('canvas');
	nc.width = nc.height = S;
	const nx = nc.getContext('2d') as CanvasRenderingContext2D;
	const id = nx.createImageData(S, S);
	for (let i = 0; i < id.data.length; i += 4) {
		const v = 128 + (Math.random() - 0.5) * 230;
		id.data[i] = id.data[i + 1] = id.data[i + 2] = v;
		id.data[i + 3] = 255;
	}
	nx.putImageData(id, 0, 0);
	const t = new T.CanvasTexture(nc);
	t.wrapS = t.wrapT = T.RepeatWrapping;
	t.colorSpace = T.NoColorSpace;
	t.repeat.set(1 / 50, 1 / 50);
	return t;
}

STRAP_HOLES.forEach((h) =>
	[h.med, h.lat].forEach((q) => {
		const sg = tctx.createRadialGradient(q[0], q[1] + 3, 0, q[0], q[1] + 3, 13.5);
		sg.addColorStop(0, 'rgba(34,22,12,0.6)');
		sg.addColorStop(0.55, 'rgba(34,22,12,0.42)');
		sg.addColorStop(1, 'rgba(34,22,12,0)');
		tctx.fillStyle = sg;
		tctx.beginPath();
		tctx.ellipse(q[0], q[1] + 3, 9, 12.2, 0, 0, Math.PI * 2);
		tctx.fill();
	}),
);
tctx.setTransform(1, 0, 0, 1, 0, 0);
